export type oidcStartResponse303 = {
  data: void;
  status: 303;
};

export type oidcStartResponseError = oidcStartResponse303 & {
  headers: Headers;
};

export type oidcStartResponse = oidcStartResponseError;

export const getOidcStartUrl = (params?: OidcStartParams) => {
  const normalizedParams = new URLSearchParams();

  Object.entries(params || {}).forEach(([key, value]) => {
    if (value !== undefined) {
      normalizedParams.append(key, value === null ? 'null' : String(value));
    }
  });

  const stringifiedParams = normalizedParams.toString();

  return stringifiedParams.length > 0
    ? `/api/v1/auth/oidc?${stringifiedParams}`
    : `/api/v1/auth/oidc`;
};

/**
 * @summary Starts single sign-on: redirects to the identity provider.
 */
export const oidcStart = async (
  params?: OidcStartParams,
  options?: Parameters<typeof apiFetch>[1],
): Promise<oidcStartResponse> => {
  return apiFetch<oidcStartResponse>(getOidcStartUrl(params), {
    ...options,
    method: 'GET',
  });
};

export type oidcCallbackResponse303 = {
  data: void;
  status: 303;
};

export type oidcCallbackResponseError = oidcCallbackResponse303 & {
  headers: Headers;
};

export type oidcCallbackResponse = oidcCallbackResponseError;

export const getOidcCallbackUrl = (params?: OidcCallbackParams) => {
  const normalizedParams = new URLSearchParams();

  Object.entries(params || {}).forEach(([key, value]) => {
    if (value !== undefined) {
      normalizedParams.append(key, value === null ? 'null' : String(value));
    }
  });

  const stringifiedParams = normalizedParams.toString();

  return stringifiedParams.length > 0
    ? `/api/v1/auth/oidc/callback?${stringifiedParams}`
    : `/api/v1/auth/oidc/callback`;
};

/**
 * @summary Completes single sign-on: verifies the provider's answer, signs the user
in, sets the refresh cookie and returns to the app. No token is put in the URL.
 */
export const oidcCallback = async (
  params?: OidcCallbackParams,
  options?: Parameters<typeof apiFetch>[1],
): Promise<oidcCallbackResponse> => {
  return apiFetch<oidcCallbackResponse>(getOidcCallbackUrl(params), {
    ...options,
    method: 'GET',
  });
};

